241:static void
242:roll_disc (struct disc *disc)
243:{
244:  double th = disc->theta;
245:  if (th < 0)
246:    th = -(th + disc->velocity);
247:  else
248:    th = (th + disc->velocity);
250:  if (th > (360*64))
251:    th -= (360*64);
252:  else if (th < 0)
253:    th += (360*64);
255:  disc->theta = (disc->theta > 0 ? th : -th);
257:  disc->velocity += disc->acceleration;
259:  if (disc->velocity > disc->limit || 
260:      disc->velocity < -disc->limit)
261:    disc->acceleration = -disc->acceleration;
263:  /* Alter direction of rotational acceleration randomly. */
264:  if (! (random() % 120))
265:    disc->acceleration = -disc->acceleration;
267:  /* Change acceleration very occasionally. */
268:  if (! (random() % 200))
269:    {
270:      if (random() & 1)
271:	disc->acceleration *= 1.2;
272:      else
273:	disc->acceleration *= 0.8;
274:    }
275:}
